<?php
require_once __DIR__.'/includes/config.php';
require_once __DIR__.'/includes/plan_limits.php';
require_owner();
$ownerId=(int)$_SESSION['user_id']; $errors=[];
$permissions=['can_sales'=>'Record sales','can_products'=>'Manage products','can_customers'=>'Manage customers','can_expenses'=>'Record expenses','can_reports'=>'View/download reports','can_inventory'=>'View stock history','can_debts'=>'Manage debts/repayments'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??''; $staffId=(int)($_POST['staff_id']??0);
 if($action==='toggle' && $staffId>0){$q=$pdo->prepare('UPDATE staff_users SET is_active=1-is_active WHERE id=? AND owner_user_id=?');$q->execute([$staffId,$ownerId]);if($q->rowCount())audit_log($pdo,'staff_status_changed','staff',(int)$staffId,'Active status toggled');flash($q->rowCount()?'Staff account status updated.':'No matching staff account found.');redirect('staff.php');}
 if($action==='create'){
  $limits=kasuwalink_plan_limits($pdo,$ownerId);$countQ=$pdo->prepare('SELECT COUNT(*) FROM staff_users WHERE owner_user_id=? AND is_active=1');$countQ->execute([$ownerId]);$staffCount=(int)$countQ->fetchColumn();if($limits['staff_limit']>0 && $staffCount >= $limits['staff_limit'])$errors[]='Your '.ucfirst($limits['plan']).' plan staff limit has been reached. Upgrade your plan or disable an existing staff account.';
  $name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';
  if(mb_strlen($name)<2||mb_strlen($name)>120)$errors[]='Enter a staff name between 2 and 120 characters.';
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email address.';
  if(strlen($password)<10)$errors[]='Staff password must contain at least 10 characters.';
  $q=$pdo->prepare('SELECT 1 FROM users WHERE email=? UNION SELECT 1 FROM staff_users WHERE email=? LIMIT 1');$q->execute([$email,$email]);if($q->fetchColumn())$errors[]='That email address is already in use.';
  $chosen=[];foreach(array_keys($permissions) as $key)$chosen[$key]=isset($_POST[$key])?1:0;
  if(!array_sum($chosen))$errors[]='Select at least one permission.';
  if(!$errors){$sql='INSERT INTO staff_users (owner_user_id,full_name,email,password_hash,'.implode(',',array_keys($permissions)).') VALUES (?,?,?,?'.str_repeat(',?',count($permissions)).')';$q=$pdo->prepare($sql);$q->execute(array_merge([$ownerId,$name,$email,password_hash($password,PASSWORD_DEFAULT)],array_values($chosen)));audit_log($pdo,'staff_account_created','staff',(int)$pdo->lastInsertId(),'Staff account created for '.$email);flash('Staff account created. Share the login details securely with the employee.');redirect('staff.php');}
 }
}
$q=$pdo->prepare('SELECT id,full_name,email,can_sales,can_products,can_customers,can_expenses,can_reports,can_inventory,can_debts,is_active,created_at FROM staff_users WHERE owner_user_id=? ORDER BY created_at DESC');$q->execute([$ownerId]);$staffList=$q->fetchAll();$pageTitle='Staff accounts';require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><div class="text-secondary small">TEAM ACCESS</div><h1 class="h3 fw-bold mb-1">Staff accounts</h1><p class="muted mb-0">Create employee logins and give each person only the access they need.</p></div></div>
