<div class="row g-4"><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Add a staff member</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="full_name" required maxlength="120" value="<?=e($_POST['full_name']??'')?>"></div><div class="mb-3"><label class="form-label">Email address (login)</label><input class="form-control" type="email" name="email" required maxlength="190" value="<?=e($_POST['email']??'')?>"></div><div class="mb-3"><label class="form-label">Temporary password</label><input class="form-control" type="password" name="password" required minlength="10" autocomplete="new-password"><div class="form-text">Use at least 10 characters. Share it securely.</div></div><h3 class="h6 fw-bold">Permissions</h3><p class="small text-secondary">A checked permission allows access to that module.</p><?php foreach($permissions as $key=>$label):?><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="<?=e($key)?>" id="<?=e($key)?>" <?=isset($_POST[$key])?'checked':''?>><label class="form-check-label" for="<?=e($key)?>"><?=e($label)?></label></div><?php endforeach;?><button class="btn btn-primary w-100 mt-3">Create staff account</button></form></div></div></div>
<div class="col-lg-7"><div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Your team</h2><?php if(!$staffList):?><div class="empty-state"><div class="fs-1 mb-2">♙</div><h3 class="h6">No staff accounts yet</h3><p class="mb-0">Create an account when you're ready to give an employee access.</p></div><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Staff member</th><th>Access</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($staffList as $staff):?><tr><td><strong><?=e($staff['full_name'])?></strong><div class="small text-secondary"><?=e($staff['email'])?></div></td><td><span class="small"><?php $labels=[];foreach($permissions as $key=>$label){if($staff[$key])$labels[]=$label;}echo e(implode(', ',$labels)?:'No modules'); ?></span></td><td><span class="badge text-bg-<?=$staff['is_active']?'success':'secondary'?>"><?=$staff['is_active']?'Active':'Disabled'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="staff_id" value="<?=(int)$staff['id']?>"><button class="btn btn-sm btn-outline-<?=$staff['is_active']?'danger':'success'?>"><?=$staff['is_active']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div><div class="alert alert-warning small mt-3 mb-0"><strong>Security note:</strong> Staff accounts access the same business workspace but only the modules selected above. The business owner retains full access. Before public deployment, enforce HTTPS and review all modules and workflows.</div></div></div>
